"use client";
import { ArtemisScope } from "./artemis-scope";
import type { ArtemisFooterContent } from "./components/footer-sections/content";
import View0 from "./components/footer-sections/variants/01-panorama";
import View1 from "./components/footer-sections/variants/02-wordmark";
import View2 from "./components/footer-sections/variants/03-landscape";
import View3 from "./components/footer-sections/variants/04-studio";
import View4 from "./components/footer-sections/variants/05-local-time";
import View5 from "./components/footer-sections/variants/06-frame";
import View6 from "./components/footer-sections/variants/07-spotlight";
import View7 from "./components/footer-sections/variants/08-mega";
import View8 from "./components/footer-sections/variants/09-cta";
const variants = {"panorama":View0,"wordmark":View1,"landscape":View2,"studio":View3,"local-time":View4,"frame":View5,"spotlight":View6,"mega":View7,"cta":View8};
export type { ArtemisFooterClock, ArtemisFooterColumn, ArtemisFooterColumnLink, ArtemisFooterContent, ArtemisFooterImage, ArtemisFooterLink, ArtemisFooterNewsletter, ArtemisFooterSocialLink } from "./components/footer-sections/content";
export interface ArtemisFooterSectionsProps { className?: string; variant?: "panorama" | "wordmark" | "landscape" | "studio" | "local-time" | "frame" | "spotlight" | "mega" | "cta"; /** The words on the footer; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisFooterContent>; }
export function ArtemisFooterSections({ className, variant = "panorama", content }: ArtemisFooterSectionsProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View content={content}/></div></ArtemisScope>;}
